insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"the_kingdoms_worst_day_homework_q01_finish","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_kingdoms_worst_day_homework.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_homework_q01_start","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_kingdoms_worst_day_homework.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"the_kingdoms_worst_day_homework_q01_finish","locale":"he","line_order":0,"content":"הלוח שוב מסודר, והשער הגדול נסגר בזמן. היום הכי גרוע של הממלכה נגמר טוב.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_homework_q01_finish","locale":"he","line_order":1,"content":"זכרו: noun = שם עצם, שם של דבר. verb = פועל, מה עושים. adjective = שם תואר, איך הדבר נראה. באנגלית הוא בא לפני שם העצם: the big gate = השער הגדול.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_homework_q01_finish","locale":"he","line_order":2,"content":"כל הכבוד. עשיתם את שיעורי הבית לבד, ומחר כל מי שעובר בשער ישמע על זה.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_homework_q01_start","locale":"he","line_order":0,"content":"איזה יום! בזכותכם היריד עבר נהדר, וכולם ליד השער עוד מדברים עליכם.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_homework_q01_start","locale":"he","line_order":1,"content":"אבל רוח הערב העיפה את כרטיסי המילים מהלוח של היריד, והכול התערבב.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_homework_q01_start","locale":"he","line_order":2,"content":"אין פה שום דבר חדש, את כל המילים אתם כבר מכירים. תראו לי שאתם יודעים לסדר את הלוח לבד.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_homework_q01_start","locale":"he","line_order":3,"content":"את כל הכרטיסים אספתי לעגלה שליד השער. צריך לסיים לפני שמחשיך.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
